<script setup lang="ts">
import { MapPin, X } from 'lucide-vue-next'
import { locationApi, type LocationApiItem, type City, type District } from '~/api/location'
const props=withDefaults(defineProps<{modelValue:boolean;location:LocationApiItem|null;loading?:boolean}>(),{loading:false});const emit=defineEmits(['update:modelValue','save'])
const form=reactive({name:'',city_id:null as number|null,district_id:null as number|null,address:'',status:'active' as 'active'|'passive'});const cities=ref<City[]>([]);const districts=ref<District[]>([]);const imageFile=ref<File|null>(null);const imagePreview=ref('');const imageInput=ref<HTMLInputElement|null>(null);const latitude=ref<number|null>(null);const longitude=ref<number|null>(null)
const fill=async(l:LocationApiItem|null)=>{if(!l)return;form.name=l.name||'';form.city_id=Number(l.city_id??l.city?.id)||null;form.district_id=Number(l.district_id??l.district?.id)||null;form.address=l.address||'';form.status=l.is_active===false?'passive':'active';imageFile.value=null;imagePreview.value=l.image||'';latitude.value=l.latitude??null;longitude.value=l.longitude??null;cities.value=await locationApi.cities();if(form.city_id)districts.value=await locationApi.districts(form.city_id)}
watch(()=>props.modelValue,open=>{if(open)fill(props.location)});watch(()=>props.location,location=>{if(props.modelValue&&location)fill(location)});watch(()=>form.city_id,async id=>{if(id)districts.value=await locationApi.districts(id);else districts.value=[]})
const close=()=>emit('update:modelValue',false);const handleImageChange=(e:Event)=>{const f=(e.target as HTMLInputElement).files?.[0];if(f&&f.size<=5*1024*1024){imageFile.value=f;imagePreview.value=URL.createObjectURL(f)}};const useCurrentLocation=()=>navigator.geolocation?.getCurrentPosition(p=>{latitude.value=p.coords.latitude;longitude.value=p.coords.longitude});const submit=()=>{emit('save',{name:form.name,city_id:form.city_id,district_id:form.district_id,address:form.address,status:form.status,file:imageFile.value,latitude:latitude.value,longitude:longitude.value});close()}
</script>
<template><Teleport to="body"><div v-if="modelValue" class="fixed inset-0 z-[9999]"><button class="absolute inset-0 h-full w-full bg-slate-950/35" @click="close"/><aside class="absolute right-0 top-0 flex h-full w-full max-w-[560px] flex-col bg-white shadow-2xl dark:bg-gray-950"><div class="flex items-start justify-between border-b px-6 py-5"><div class="flex items-start gap-3"><div class="flex h-11 w-11 items-center justify-center rounded-xl bg-brand-50 text-brand-500"><MapPin :size="20"/></div><div><h2 class="text-xl font-semibold">Lokasyon Düzenle</h2><p class="mt-1 text-sm text-gray-500">Lokasyon bilgilerini güncelleyin.</p></div></div><button type="button" @click="close"><X :size="22"/></button></div><form class="relative flex min-h-0 flex-1 flex-col" @submit.prevent="submit"><div v-if="loading" class="absolute inset-0 z-10 flex flex-col items-center justify-center gap-3 bg-white/80 dark:bg-gray-950/80"><span class="h-8 w-8 animate-spin rounded-full border-2 border-gray-200 border-t-brand-500 dark:border-gray-700"/><span class="text-sm text-gray-500 dark:text-gray-400">Lokasyon bilgileri yükleniyor...</span></div><div class="flex-1 space-y-6 overflow-y-auto px-6 py-6"><div><label class="mb-2 block text-sm font-semibold">Lokasyon Resmi</label><div class="flex items-center gap-4 rounded-xl border p-4"><div class="flex h-24 w-24 shrink-0 items-center justify-center overflow-hidden rounded-xl bg-gray-100"><img v-if="imagePreview" :src="imagePreview" class="h-full w-full object-cover"/><MapPin v-else :size="28" class="text-gray-400"/></div><div><p class="text-sm font-medium">Lokasyon görseli</p><p class="mt-1 text-xs text-gray-500">PNG, JPG veya WEBP · Maks. 5MB</p><input ref="imageInput" type="file" accept="image/png,image/jpeg,image/webp" class="hidden" @change="handleImageChange"/><button type="button" class="mt-3 rounded-lg border px-3 py-2 text-xs font-semibold" @click="imageInput?.click()">{{imageFile?'Resmi Değiştir':'Resim Seç'}}</button></div></div></div><div><label class="mb-2 block text-sm font-semibold">Lokasyon Adı *</label><input v-model="form.name" required class="h-12 w-full rounded-lg border px-4 text-sm"/></div><div class="grid grid-cols-1 gap-4 sm:grid-cols-2"><div><label class="mb-2 block text-sm font-semibold">İl *</label><select v-model="form.city_id" required class="h-12 w-full rounded-lg border px-4 text-sm"><option :value="null">İl seçin</option><option v-for="city in cities" :key="city.id" :value="city.id">{{city.name}}</option></select></div><div><label class="mb-2 block text-sm font-semibold">İlçe *</label><select v-model="form.district_id" required :disabled="!form.city_id" class="h-12 w-full rounded-lg border px-4 text-sm"><option :value="null">İlçe seçin</option><option v-for="district in districts" :key="district.id" :value="district.id">{{district.name}}</option></select></div></div><div><label class="mb-2 block text-sm font-semibold">Açık Adres *</label><textarea v-model="form.address" required rows="4" class="w-full resize-none rounded-lg border px-4 py-3 text-sm"/></div><div><label class="mb-2 block text-sm font-semibold">Lokasyon Konumu</label><div class="relative h-36 overflow-hidden rounded-xl border bg-[#edf2f7]"><div class="absolute inset-0 bg-[linear-gradient(135deg,#edf2f7,#f8fafc)]"/><div class="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2"><MapPin :size="25" class="text-brand-500"/></div></div><button type="button" class="mt-2 rounded-lg border px-3 py-2 text-xs font-semibold" @click="useCurrentLocation">Mevcut Konumu Kullan</button></div><div class="flex items-center justify-between rounded-xl border px-4 py-4"><div><p class="text-sm font-semibold">Durum</p><p class="mt-1 text-xs text-gray-500">Lokasyonun aktiflik durumunu yönetin.</p></div><button type="button" role="switch" :aria-checked="form.status==='active'" class="relative h-6 w-11 rounded-full" :class="form.status==='active'?'bg-brand-500':'bg-gray-300'" @click="form.status=form.status==='active'?'passive':'active'"><span class="absolute top-1 h-4 w-4 rounded-full bg-white" :class="form.status==='active'?'left-6':'left-1'"/></button></div></div><div class="flex justify-end gap-3 border-t px-6 py-4"><button type="button" class="rounded-lg border px-4 py-2.5 text-sm font-semibold" @click="close">İptal</button><button type="submit" :disabled="loading" class="rounded-lg bg-brand-500 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50">Değişiklikleri Kaydet</button></div></form></aside></div></Teleport></template>
